import json,re
p='/Users/alexandremasmejean/.codex/.chatgpt-projects/g-p-6ad59c015c308191aa21cba63c71a6dc/sites/liberer-la-retraite/dist/corpus/securite-sociale.json'
s=json.load(open(p))
for number in ['L162-17','L162-14-1','L162-16-1','L162-16','L162-16-4']:
 a=next(a for a in s if a['number']==number)
 if number=='L162-14-1':
  xml=a['source_xml']; start=xml.find('II.'); end=xml.find('III.',start); print('\\n===',number,'II ===\\n'+xml[start:end])
 elif number=='L162-17':
  print('\\n===',number,'deux premiers alinéas ===')
  print('\\n'.join(re.findall(r'<p\\b["'^>]*>.*?</p>'"',a['source_xml'],re.S)[:2]))
 else: print(number,'corpus même source:',a['source_id'])
print('\\n=== Renvois par alinéa ou phrase aux articles du lot ===')
pat=re.compile(r'(?:alinéa|alinéas|phrase).{0,160}?L\\.\\s*162-(?:15|16)(?:-\\d+)*',re.S)
for a in s:
 for m in pat.finditer(a['source_xml']):
  print(a['number'],re.sub(r'\\s+',' ',m.group()))
PY"

